class Solution:
    def divisibleSubstrings(self, word):
        mp = {c: i + 1 for i, c in enumerate("qwertyuiopasdfghjklzxcvbnm")}
        n = len(word); ans = 0
        for i in range(n):
            s = 0
            for j in range(i, n):
                s += mp[word[j]]
                if s % (j - i + 1) == 0:
                    ans += 1
        return ans

