class Solution {
public:
    int divisibleSubstrings(string word) {
        string q = "qwertyuiopasdfghjklzxcvbnm";
        int mp[26];
        for (int i = 0; i < 26; i++) mp[q[i] - 'a'] = i + 1;
        int n = word.size(), ans = 0;
        for (int i = 0; i < n; i++) {
            int s = 0;
            for (int j = i; j < n; j++) {
                s += mp[word[j] - 'a'];
                if (s % (j - i + 1) == 0) ans++;
            }
        }
        return ans;
    }
};

